window.PORTAL={"day": 7, "title": "HIE + Neonatal Seizures", "docTitle": "DAY 7 — HIE + NEONATAL SEIZURES", "subtitle": ["Birth Asphyxia • Therapeutic Hypothermia • aEEG/EEG", "NEET-SS + ICP Paediatrics 2026 Master Course | Premium Core-Day Standard"], "source": "source/Day_7_NEET_SS_ICP_Paediatrics_2026_V3_HIE_Asphyxia_TH_Seizures_aEEG_EEG.docx", "pages": [{"id": "overview", "title": "Overview", "group": "Start", "kind": "overview", "sections": [{"title": "", "blocks": [{"t": "p", "html": "<strong>Birth Asphyxia • Therapeutic Hypothermia • aEEG/EEG</strong>"}, {"t": "p", "html": "NEET-SS + ICP Paediatrics 2026 Master Course | Premium Core-Day Standard"}, {"t": "callout", "label": "SCHEDULE MAPPING", "title": "", "html": ["05 Oct 2026 = Day 7. This document covers only the locked Day 7 topics: HIE, birth asphyxia, therapeutic hypothermia, neonatal seizures and aEEG/EEG. No future-topic leakage."], "fill": "1F4E79"}, {"t": "callout", "label": "REFERENCE HIERARCHY", "title": "", "html": ["PRIMARY TEXTBOOK: Nelson Textbook of Pediatrics, 22nd Edition. Supplementary references used for refinement/verification: current AAP 2026 Therapeutic Hypothermia Clinical Report; 2025 AHA/AAP Neonatal Resuscitation guidance; ILAE neonatal seizure treatment recommendations; Volpe’s Neurology of the Newborn; Cloherty &amp; Stark’s Manual of Neonatal Care. Where recommendations differ, the guideline/framework is named explicitly."], "fill": "806000"}, {"t": "callout", "label": "GUIDELINE CURRENCY", "title": "", "html": ["Current AAP 2026: standard evidence-based cooling = target 33.5°C (clinical target range commonly 33.5–34.5°C), begin within 6 h when possible, continue 72 h, then slow rewarming about 0.5°C/h. Strongest evidence is for moderate-to-severe HIE at ≥36 weeks. 35+0 to 35+6 weeks requires individualized expert/family discussion; &lt;35 weeks is not recommended. Mild HIE is not routinely cooled outside evidence-generating protocols."], "fill": "1F4E79"}, {"t": "list", "ordered": false, "items": ["Distinguish birth asphyxia, neonatal encephalopathy and HIE; avoid using low Apgar alone as a diagnosis.", "Reconstruct the primary and secondary energy-failure phases and explain why the first 6 hours are the therapeutic window.", "Grade encephalopathy clinically and recognize moderate/severe HIE or seizures that trigger urgent cooling assessment.", "Apply contemporary therapeutic-hypothermia eligibility, timing, temperature, duration and rewarming principles.", "Anticipate cooling-related physiology and complications: bradycardia, hypotension, coagulopathy, thrombocytopenia, electrolyte shifts, altered drug clearance and skin injury.", "Recognize neonatal seizures clinically and electrographically; distinguish seizures from common mimics.", "Use phenobarbital appropriately as first-line therapy for most neonatal seizures and select second-line therapy rationally.", "Interpret basic aEEG/EEG backgrounds, sleep-wake cycling, seizures and status patterns, while understanding aEEG limitations.", "Integrate MRI timing/patterns, multiorgan injury and neuroprognostication without making premature deterministic predictions.", "Solve high-level next-step vignettes that combine resuscitation history, blood gas, neurologic exam, EEG and cooling decisions."]}, {"t": "table", "head": ["<strong>Objective</strong>", "<strong>Skill</strong>", "<strong>Mapped case(s)</strong>", "<strong>Mapped MCQ(s)</strong>"], "rows": [["1", "Asphyxia vs encephalopathy vs HIE", "Case 1 / 2", "1, 8, 21, 47"], ["2", "Energy failure / therapeutic window", "Case 2", "9, 22, 40, 61"], ["3", "Grade HIE / identify seizures", "Case 2 / 4", "3, 11, 23, 46"], ["4", "Cooling eligibility &amp; protocol", "Case 3 / 4", "4, 12, 24, 35, 52, 63"], ["5", "Cooling physiology/complications", "Case 5", "14, 26, 43, 58"], ["6", "Recognize neonatal seizure &amp; mimics", "Case 6 / 7", "5, 16, 29, 44, 66"], ["7", "ASM choice and escalation", "Case 7 / 8", "6, 17, 30, 45, 59, 67"], ["8", "aEEG/EEG interpretation", "Case 6 / 9", "7, 18, 31, 48, 60, 70"], ["9", "MRI/prognosis/follow-up", "Case 10", "19, 32, 49, 71"], ["10", "Integrated next-step reasoning", "Cases 1–10", "33–39, 50–57, 62–75"]]}, {"t": "table", "head": ["<strong>Time</strong>", "<strong>Focus</strong>"], "rows": [["0:00–0:35", "Birth asphyxia vs neonatal encephalopathy vs HIE; primary/secondary energy failure"], ["0:35–1:15", "Clinical HIE grading; cooling eligibility; 2026 AAP nuances"], ["1:15–1:55", "Therapeutic hypothermia delivery, monitoring, complications and rewarming"], ["1:55–2:35", "Neonatal seizure recognition, mimics, causes and antiseizure treatment"], ["2:35–3:05", "aEEG/EEG: background, seizure patterns, sleep-wake cycling, pitfalls"], ["3:05–3:30", "MRI patterns, prognostication, multiorgan care and follow-up"], ["3:30–4:00", "75 MCQs + targeted review; Active Recall answers checked after attempt"]]}]}]}, {"id": "part-1", "title": "Birth Asphyxia, Neonatal Encephalopathy & HIE", "eyebrow": "Part I", "group": "Study Notes", "kind": "notes", "sections": [{"title": "1. Definitions: Do Not Collapse Three Different Concepts", "blocks": [{"t": "table", "head": ["<strong>Term</strong>", "<strong>Exam-safe meaning</strong>", "<strong>Major trap</strong>"], "rows": [["Birth/perinatal asphyxia", "Impaired placental/pulmonary gas exchange causing hypoxemia ± hypercapnia and metabolic acidosis with potential organ dysfunction.", "A low Apgar alone does not prove asphyxia."], ["Neonatal encephalopathy", "Syndrome of disturbed neurologic function in a newborn: altered consciousness/tone/reflexes, respiratory drive, feeding or seizures.", "Etiology can be HIE, infection, stroke, metabolic/genetic disease, hemorrhage, drug exposure, etc."], ["Hypoxic-ischemic encephalopathy (HIE)", "Neonatal encephalopathy attributable to hypoxic-ischemic injury around birth, supported by perinatal course, biochemistry, neurologic phenotype and exclusion of compelling alternatives.", "Do not demand a single “sentinel event” before starting time-critical cooling when criteria are otherwise met."]]}, {"t": "callout", "label": "CRITICAL TRAP", "title": "", "html": ["Apgar score predicts need for resuscitation and contributes context, but it is not a stand-alone biochemical or etiologic diagnosis of HIE. Cord/early blood gas, resuscitation course, neurologic exam, seizures and organ injury matter."], "fill": "9C0006"}]}, {"title": "2. Mechanistic Pathophysiology — WHAT → WHY → HOW → RECOGNIZE → WHAT NEXT", "blocks": [{"t": "table", "head": ["<strong>WHAT</strong>", "<strong>WHY</strong>", "<strong>HOW</strong>", "<strong>RECOGNIZE</strong>", "<strong>WHAT NEXT</strong>"], "rows": [["Acute interruption of oxygen/blood flow", "Oxidative phosphorylation fails", "ATP falls → Na/K pump failure → depolarization, glutamate release, Ca²⁺ influx", "Bradycardia, acidosis, depressed tone/respiration; early neurologic dysfunction", "Resuscitate effectively, avoid hyperthermia, obtain early gas, reassess neurologic state"], ["Primary energy failure", "Cellular energy stores depleted", "Cytotoxic edema + excitotoxicity + free radicals", "Initial depression; may partially recover after reperfusion", "Identify infants at risk; do not be reassured by transient recovery"], ["Latent phase", "Partial metabolic recovery after reperfusion", "Window before delayed mitochondrial failure/inflammation", "Infant may appear “better” while injury cascade evolves", "This is the rationale for starting hypothermia as early as possible, ideally &lt;6 h"], ["Secondary energy failure", "Mitochondrial dysfunction + inflammation + apoptosis", "Seizures, cerebral edema and delayed cell death", "Encephalopathy/seizures can intensify 6–48 h", "Continuous neuromonitoring; supportive care; cooling attenuates this phase"], ["Tertiary phase", "Persistent inflammation / altered repair", "Longer-term network and developmental effects", "Motor/cognitive/hearing/vision/epilepsy risk may emerge later", "Structured neurodevelopmental follow-up and early intervention"]]}, {"t": "callout", "label": "EXAM PEARL", "title": "", "html": ["The classic “6-hour window” is mechanistic: cooling is most effective when started during the latent phase before secondary energy failure is established. Do not delay cooling for MRI."], "fill": "806000"}]}, {"title": "3. HIE Clinical Severity — Modified Sarnat Logic", "blocks": [{"t": "table", "head": ["<strong>Domain</strong>", "<strong>Mild</strong>", "<strong>Moderate</strong>", "<strong>Severe</strong>"], "rows": [["Level of consciousness", "Hyperalert / irritable", "Lethargic", "Stupor/coma"], ["Activity", "Normal or increased", "Decreased", "Absent/minimal"], ["Tone", "Normal / increased", "Hypotonia", "Flaccid"], ["Posture", "Mild distal flexion", "Strong distal flexion / extension", "Decerebrate or no posture"], ["Primitive reflexes", "Suck/Moro may be brisk", "Weak/incomplete", "Absent"], ["Autonomic features", "Often sympathetic", "Often parasympathetic / variable", "Brainstem dysfunction; variable pupils, HR, respiration"], ["Seizures", "Uncommon", "Common", "May occur, then disappear with profound suppression"], ["EEG/aEEG background", "Usually normal or mildly abnormal", "Abnormal/discontinuous", "Burst suppression, low voltage or inactive background"]]}, {"t": "callout", "label": "HIGH-YIELD DISTINCTION", "title": "", "html": ["Moderate-to-severe encephalopathy or seizures drive standard cooling eligibility when the infant also fits the perinatal/biochemical framework. Mild HIE alone remains an evidence gap; routine cooling is not yet established."], "fill": "1F4E79"}]}, {"title": "4. Evidence of Peripartum Hypoxic-Ischemic Stress", "blocks": [{"t": "p", "html": "Trial-derived frameworks combine (A) biochemical/resuscitation evidence and (B) moderate/severe encephalopathy or seizures. Exact local protocols differ; for exams, identify the named framework and do not mix criteria."}, {"t": "table", "head": ["<strong>Evidence domain</strong>", "<strong>Classic trial-derived examples</strong>", "<strong>How to use</strong>"], "rows": [["Severe acidosis", "Cord or blood gas within ~1 h: pH ≤7.00 or base deficit ≥16 mmol/L", "Strong biochemical trigger to proceed to neurologic eligibility assessment."], ["Borderline gas", "pH 7.01–7.15 or base deficit 10–15.9 mmol/L", "Usually requires additional evidence such as acute perinatal event plus low 10-min Apgar or prolonged ventilation, depending on protocol."], ["Resuscitation depression", "Apgar ≤5 at 10 min or continued ventilation/resuscitation at 10 min", "Supports significant intrapartum compromise but does not replace neurologic examination."], ["Neurologic criterion", "Moderate/severe encephalopathy on exam OR clinical/electrographic seizures", "Required for standard trial-based cooling pathways; re-examine because encephalopathy evolves."]]}, {"t": "callout", "label": "2026 AAP UPDATE", "title": "", "html": ["Standard evidence: ≥36 0/7 weeks, moderate-to-severe HIE, initiate within 6 h, 33.5°C for 72 h. For 35 0/7–35 6/7 weeks, evidence is limited and decision-making should be individualized with family discussion; &lt;35 weeks is not recommended. Cooling started 6–24 h may be considered in selected infants after discussing uncertain/smaller benefit and risks."], "fill": "1F4E79"}]}]}, {"id": "part-2", "title": "Therapeutic Hypothermia", "eyebrow": "Part II", "group": "Study Notes", "kind": "notes", "sections": [{"title": "5. Standard Whole-Body Cooling Prescription", "blocks": [{"t": "table", "head": ["<strong>Element</strong>", "<strong>Exam-standard</strong>"], "rows": [["Who", "Infant with moderate-to-severe HIE who meets protocol criteria; strongest evidence at ≥36 weeks"], ["Start", "As early as possible, ideally within 6 h after birth"], ["Target core temperature", "33.5°C target; accepted protocol range approximately 33.5–34.5°C depending on device/protocol"], ["Duration", "72 h"], ["Rewarming", "Slowly, about 0.5°C/hour until normothermia"], ["Neuromonitoring", "Continuous EEG when available; aEEG useful for trend/screening but does not replace conventional EEG"], ["Avoid", "Hyperthermia; unmonitored passive overcooling; deeper or longer cooling outside evidence-based protocol"]]}, {"t": "callout", "label": "MUST-KNOW NUMBER", "title": "", "html": ["33.5°C • within 6 hours • 72 hours • rewarm ~0.5°C/hour. These four numbers are repeatedly tested."], "fill": "806000"}]}, {"title": "6. Cooling: What Changes Physiologically?", "blocks": [{"t": "table", "head": ["<strong>Finding during cooling</strong>", "<strong>Interpretation / action</strong>"], "rows": [["Sinus bradycardia", "Expected to a degree as metabolic rate falls; evaluate perfusion and rhythm rather than treating the number alone."], ["Hypotension / low cardiac output", "May reflect HIE, myocardial injury, vasodilation or cooling; use clinical/echo-guided hemodynamic assessment."], ["Thrombocytopenia / coagulopathy", "Common in HIE and can be accentuated by cooling; clinically significant bleeding drives correction."], ["Electrolyte shifts", "K, Ca, Mg and glucose disturbances can occur; monitor serially, especially through rewarming."], ["Reduced drug clearance", "Hepatic/renal dysfunction + hypothermia may prolong sedative/ASM exposure; avoid reflexive repeated dosing without reassessment."], ["Skin/subcutaneous injury", "Check pressure points and perfusion; avoid direct cold injury."], ["Pulmonary hypertension", "May coexist with asphyxia/HIE; manage oxygenation and hemodynamics carefully."]]}, {"t": "callout", "label": "CRITICAL TRAP", "title": "", "html": ["Do not “correct” expected cooling-associated bradycardia simply to normalize heart rate if blood pressure and perfusion are acceptable. Treat the infant’s hemodynamics, not an isolated monitor number."], "fill": "9C0006"}]}, {"title": "7. Rewarming", "blocks": [{"t": "list", "ordered": true, "items": ["After 72 h of cooling, increase core temperature gradually, commonly ~0.5°C per hour, using servo control.", "Continue EEG/aEEG through rewarming because seizure burden may increase during this phase.", "Monitor blood pressure, perfusion, glucose and electrolytes; vasodilation can unmask hypotension.", "Avoid rebound hyperthermia; fever after HIE is associated with worse outcomes and should be actively prevented.", "Do not accelerate rewarming merely because the neurologic examination appears improved."]}]}]}, {"id": "part-3", "title": "Neonatal Seizures", "eyebrow": "Part III", "group": "Study Notes", "kind": "notes", "sections": [{"title": "8. Why Neonatal Seizures Are Different", "blocks": [{"t": "table", "head": ["<strong>WHAT</strong>", "<strong>WHY</strong>", "<strong>HOW</strong>", "<strong>RECOGNIZE</strong>", "<strong>WHAT NEXT</strong>"], "rows": [["Immature cortical networks", "Excitatory/inhibitory balance differs from older brain", "GABA may be relatively depolarizing; connectivity incomplete", "Seizures can be subtle, focal, autonomic or electrographic-only", "Use EEG confirmation rather than relying on dramatic convulsions"], ["Acute provoked seizure", "Brain insult lowers seizure threshold", "HIE, stroke, hemorrhage, infection, hypoglycemia/electrolytes", "Seizures cluster early with identifiable acute cause", "Treat cause + seizure; discontinuation before discharge is often appropriate once acute provoked seizures resolve"], ["Neonatal-onset epilepsy", "Channelopathy/metabolic/genetic disorder", "Recurrent seizures not explained by transient acute insult", "Family history, stereotyped recurrent events, abnormal interictal EEG or syndrome pattern", "Targeted genetic/metabolic evaluation; sodium-channel blocker may be preferred in channelopathy"]]}]}, {"title": "9. Clinical Seizure vs Mimic", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Epileptic seizure favors</strong>", "<strong>Mimic favors</strong>"], "rows": [["Provocation", "Spontaneous/stereotyped", "Stimulus-sensitive"], ["Restraint", "Persists despite holding limb", "Jitteriness often stops with gentle flexion/restraint"], ["Ocular/autonomic signs", "Forced eye deviation, apnea, HR/BP change may occur", "Jitteriness usually lacks sustained ocular deviation"], ["Rhythmicity/evolution", "Evolving frequency, amplitude or spatial spread on EEG", "Tremor lacks electrographic evolution"], ["EEG correlate", "Electrographic seizure confirms", "No ictal EEG correlate suggests nonepileptic event, though some clinical-only events require expert review"]]}, {"t": "callout", "label": "EXAM PEARL", "title": "", "html": ["After antiseizure medication, clinical movements can stop while electrographic seizures continue (“electroclinical dissociation”). This is why continuous EEG is critical in HIE."], "fill": "806000"}]}, {"title": "10. Common Causes by Timing/Context", "blocks": [{"t": "table", "head": ["<strong>Cause</strong>", "<strong>Clue</strong>"], "rows": [["HIE", "Most common cause of acute symptomatic neonatal seizures; onset often within first 24 h"], ["Arterial ischemic stroke", "Well-appearing term infant with focal clonic seizures, often after 12–72 h"], ["Intracranial hemorrhage", "Prematurity/trauma/coagulopathy; focal or multifocal seizures"], ["Hypoglycemia / Ca / Mg / Na disorder", "Check immediately because reversible"], ["CNS infection", "Sepsis signs, temperature instability, CSF abnormalities; HSV may present with seizures"], ["Pyridoxine-dependent epilepsy", "Refractory seizures; diagnostic therapeutic trial under monitoring in appropriate setting"], ["KCNQ2/SCN2A-related epilepsy", "Very early recurrent seizures; sodium-channel–targeted therapy may be important depending on genotype/phenotype"]]}]}, {"title": "11. Antiseizure Medication Strategy", "blocks": [{"t": "table", "head": ["<strong>Step</strong>", "<strong>Drug / principle</strong>", "<strong>Key exam point</strong>"], "rows": [["1", "Phenobarbital", "ILAE first-line ASM for most neonatal seizures regardless of etiology; especially established for acute symptomatic seizures. Common loading 20 mg/kg IV; additional 10 mg/kg increments may be used to a protocol maximum (often 40 mg/kg total)."], ["2", "If seizures persist", "Levetiracetam, phenytoin/fosphenytoin, midazolam or lidocaine depending on clinical context, cardiac status, EEG and local protocol. Do not assume levetiracetam is more effective first-line merely because it is perceived as “safer.”"], ["Special etiology", "Sodium-channel blocker", "Consider phenytoin/carbamazepine-type strategy in suspected channelopathy such as KCNQ2/SCN2A neonatal epilepsy under specialist guidance."], ["Acute provoked seizures resolved", "Consider stopping ASM before discharge", "ILAE supports discontinuation after acute provoked neonatal seizures resolve and neonatal-onset epilepsy is not suspected, regardless of MRI/EEG residual abnormalities, with individualized specialist review."]]}, {"t": "callout", "label": "DOSE SAFETY", "title": "", "html": ["Phenobarbital loading: 20 mg/kg IV is the classic first load; monitor respiration and blood pressure. Additional loading should follow NICU protocol and cumulative exposure. Correct glucose/electrolytes and treat infection/stroke/HIE simultaneously."], "fill": "1F4E79"}]}]}, {"id": "part-4", "title": "aEEG & Conventional EEG", "eyebrow": "Part IV", "group": "Study Notes", "kind": "notes", "sections": [{"title": "12. What aEEG Actually Shows", "blocks": [{"t": "p", "html": "Amplitude-integrated EEG compresses one or two EEG channels over time to display the envelope of minimum and maximum amplitudes. It is excellent for bedside trend recognition, background continuity and seizure-burden screening, but it sacrifices spatial and frequency detail."}, {"t": "table", "head": ["<strong>Pattern</strong>", "<strong>Typical meaning</strong>", "<strong>Trap</strong>"], "rows": [["Continuous normal voltage (CNV)", "Upper margin usually &gt;10 µV and lower margin &gt;5 µV with continuity; reassuring in context", "A normal aEEG does not exclude all focal/brief seizures."], ["Discontinuous normal voltage (DNV)", "Discontinuous background with preserved upper amplitude; can be maturational or abnormal depending on GA/context", "Interpret with gestational age and clinical state."], ["Burst suppression", "Bursts separated by very low-voltage interburst periods", "Severely abnormal background; can be influenced by medications."], ["Continuous low voltage", "Persistently low-amplitude tracing", "Severe dysfunction"], ["Flat/inactive trace", "Very low activity", "Grave background but check technical artifact, leads and medications."], ["Sleep-wake cycling", "Cyclic bandwidth narrowing/widening", "Return of cycling is generally favorable but not a stand-alone prognosis."]]}]}, {"title": "13. How a Seizure Appears on aEEG", "blocks": [{"t": "list", "ordered": true, "items": ["A seizure usually produces a sudden rise in the lower and upper margins of the aEEG band, often with a characteristic “saw-tooth” recurrent appearance when seizures repeat.", "Always inspect the raw EEG trace corresponding to the event; movement/electrode artifact can falsely elevate the band.", "Brief, low-amplitude, focal or distant-from-electrode seizures may be missed by limited-channel aEEG.", "Conventional multichannel video EEG is the gold standard for seizure diagnosis, burden and response to treatment."]}, {"t": "callout", "label": "CLOSE-DISTRACTOR DISCRIMINATOR", "title": "", "html": ["aEEG is best for continuous bedside trend + background + seizure screening. Conventional EEG is best for definitive seizure diagnosis, localization, morphology and treatment-response assessment."], "fill": "843C0C"}]}, {"title": "14. Conventional EEG — Essential Terms", "blocks": [{"t": "table", "head": ["<strong>Term</strong>", "<strong>Meaning / exam point</strong>"], "rows": [["Electrographic seizure", "Abnormal repetitive, evolving, stereotyped EEG pattern with a clear beginning/end; neonatal definitions rely on evolution and duration rather than adult semiology."], ["Electrographic-only seizure", "Ictal EEG pattern without obvious clinical change; common after ASM and in critically ill neonates."], ["Seizure burden", "Cumulative minutes of seizure per hour; high burden/status is associated with worse injury/outcomes."], ["Status epilepticus", "Historically &gt;50% of a 1-h epoch in neonatal EEG literature; modern reporting emphasizes seizure burden and continuous/recurrent ictal activity."], ["Background recovery", "Improvement in continuity, voltage and sleep-wake cycling over time is prognostically useful when integrated with exam/MRI."]]}]}]}, {"id": "part-5", "title": "MRI, Multiorgan Care & Prognosis", "eyebrow": "Part V", "group": "Study Notes", "kind": "notes", "sections": [{"title": "15. Characteristic MRI Injury Patterns", "blocks": [{"t": "table", "head": ["<strong>Pattern</strong>", "<strong>Typical insult</strong>", "<strong>Structures</strong>", "<strong>Exam clue</strong>"], "rows": [["Acute profound / sentinel-type", "Severe abrupt interruption", "Basal ganglia-thalami, perirolandic cortex, posterior limb internal capsule", "Motor outcome risk; deep gray injury"], ["Partial prolonged", "Less severe but sustained hypoxia-ischemia", "Watershed parasagittal cortex/subcortical white matter", "Later cognitive/language deficits may predominate"], ["Near-total injury", "Very severe prolonged insult", "Diffuse cortex + deep gray + white matter", "Severe encephalopathy and poor prognosis"], ["Focal arterial stroke", "Embolic/thrombotic vascular event", "Arterial territory", "Focal seizures in otherwise relatively alert term infant"]]}, {"t": "callout", "label": "MRI TIMING PEARL", "title": "", "html": ["Diffusion-weighted MRI is most sensitive early, but diffusion abnormalities can pseudonormalize later. Many units target MRI around days 4–7 after rewarming/clinical stabilization, with protocol-specific timing. Never delay time-critical cooling for MRI."], "fill": "806000"}]}, {"title": "16. Multiorgan Injury Checklist", "blocks": [{"t": "table", "head": ["<strong>System</strong>", "<strong>Common issue</strong>", "<strong>Monitoring/action</strong>"], "rows": [["Renal", "AKI/oliguria", "Urine output, creatinine, fluids, drug dosing"], ["Cardiac", "Myocardial dysfunction, hypotension", "BP/perfusion, lactate, ECG, troponin/echo when indicated"], ["Hepatic", "Transaminitis/coagulopathy", "LFT, PT/INR, bleeding"], ["Pulmonary", "PPHN / respiratory failure", "Oxygenation, ventilation, echo if needed"], ["Metabolic", "Glucose, Ca, Mg, Na abnormalities", "Serial bedside/lab monitoring; avoid hypoglycemia"], ["Hematologic", "Thrombocytopenia/DIC", "CBC/coagulation; treat clinically significant bleeding"], ["GI", "Feeding intolerance / gut injury risk", "Individualized enteral feeding strategy during cooling per unit protocol"]]}]}, {"title": "17. Prognostication: Multimodal, Serial, Humble", "blocks": [{"t": "list", "ordered": false, "items": ["No single variable should be used alone. Combine serial neurologic examination, seizure burden, EEG/aEEG background evolution, MRI pattern, organ dysfunction and trajectory.", "Severely suppressed EEG background that fails to recover is concerning; improvement in background and sleep-wake cycling is favorable but not deterministic.", "MRI deep-gray injury and abnormal posterior limb internal capsule are associated with adverse motor outcomes; watershed injury may predict later cognitive/language deficits.", "Sedation, ASM, hypothermia and metabolic instability can confound exam and EEG.", "All infants treated with therapeutic hypothermia require structured neurodevelopmental follow-up with hearing, vision, motor, feeding, cognition/language and epilepsy surveillance."]}]}]}, {"id": "numbers", "title": "Must-Know Numbers", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Number / rule</strong>", "<strong>Meaning</strong>"], "rows": [["≥36 0/7 weeks", "Strongest AAP 2026 evidence base for routine TH in moderate-to-severe HIE"], ["35 0/7–35 6/7 weeks", "Limited evidence; individualized expert/family discussion"], ["&lt;35 weeks", "Therapeutic hypothermia not recommended by current AAP clinical report"], ["≤6 h", "Optimal initiation window"], ["6–24 h", "May be considered selectively; benefit less certain"], ["33.5°C target", "Standard whole-body cooling target; protocols often operate within ~33.5–34.5°C"], ["72 h", "Standard cooling duration"], ["~0.5°C/h", "Typical rewarming rate"], ["pH ≤7.00 or BD ≥16", "Classic severe biochemical trial-entry trigger"], ["Apgar ≤5 at 10 min", "Classic resuscitation criterion in trial-derived pathways"], ["Phenobarbital 20 mg/kg IV", "Classic first loading dose for neonatal seizures"], ["50% of 1 h", "Historic neonatal EEG status-burden threshold; modern reports emphasize seizure burden/continuous ictal activity"]]}]}]}, {"id": "tables", "title": "Tables & Algorithms", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "HIE vs Stroke vs Hypoglycemic Brain Injury vs Sepsis/Encephalitis", "h1": "Part VII — Comparison Tables", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>HIE</strong>", "<strong>Stroke</strong>", "<strong>Hypoglycemia</strong>", "<strong>Infection</strong>"], "rows": [["Perinatal depression", "Common", "Often absent", "Variable", "Variable"], ["Seizures", "Common, often early", "Often focal, later first days", "Possible", "Possible"], ["Encephalopathy", "Diffuse", "May be mild except seizures", "Variable", "Diffuse"], ["MRI", "BGT/watershed patterns", "Arterial territory", "Posterior-predominant cortex/WM possible", "Meningoencephalitic pattern"], ["Key discriminator", "Global perinatal insult + evolving encephalopathy", "Focal vascular lesion", "Documented low glucose + compatible injury", "Inflammatory/infectious evidence"]]}]}, {"title": "Clinical Event vs Jitteriness vs Benign Sleep Myoclonus", "h1": "", "blocks": [{"t": "table", "head": ["<strong>Feature</strong>", "<strong>Seizure</strong>", "<strong>Jitteriness</strong>", "<strong>Benign sleep myoclonus</strong>"], "rows": [["Stimulus sensitive", "Usually no", "Often yes", "Occurs in sleep"], ["Stops with restraint", "No", "Often yes", "May stop with arousal"], ["Eye deviation/autonomic change", "Can occur", "No", "No"], ["EEG ictal correlate", "Yes if epileptic", "No", "No"], ["Next step", "EEG + cause + ASM if confirmed", "Correct metabolic/stimulus issues", "Reassure after correct diagnosis"]]}]}, {"title": "Algorithm 1 — Depressed Newborn → Cooling Decision", "h1": "Part VIII — Exam Algorithms", "blocks": [{"t": "list", "ordered": true, "items": ["Stabilize using NRP principles; support ventilation, circulation and glucose; avoid hyperthermia.", "Obtain cord blood gas or earliest blood gas (ideally within first hour) in a significantly depressed infant.", "Review 10-min Apgar, duration/type of resuscitation and evidence of acute perinatal compromise.", "Perform structured neurologic exam and repeat because encephalopathy evolves.", "If moderate/severe encephalopathy or seizures plus protocol-level evidence of hypoxic-ischemic stress: activate cooling pathway immediately.", "Begin servo-controlled whole-body cooling as early as possible, ideally &lt;6 h; transfer promptly if needed.", "Start continuous EEG/aEEG, multiorgan monitoring and serial labs; treat seizures and reversible metabolic abnormalities.", "Continue 72 h then rewarm slowly ~0.5°C/h; continue neuromonitoring through rewarming."]}]}, {"title": "Algorithm 2 — Suspected Neonatal Seizure", "h1": "", "blocks": [{"t": "list", "ordered": true, "items": ["ABCs + bedside glucose immediately; correct glucose/electrolytes and stabilize cardiorespiratory status.", "Determine whether event is stereotyped, spontaneous and not suppressible; obtain video if safe.", "Initiate conventional continuous EEG whenever available; use aEEG as adjunct/trend tool.", "Investigate cause: HIE, stroke/hemorrhage, infection, metabolic/electrolyte, congenital/genetic/epilepsy.", "If electrographic seizure confirmed or high clinical urgency: phenobarbital 20 mg/kg IV first-line for most acute neonatal seizures.", "Reassess EEG response; if persistent, choose second-line ASM based on etiology/hemodynamics and specialist guidance.", "For refractory unexplained seizures, escalate metabolic/genetic work-up including treatable vitamin-responsive epilepsies.", "After acute provoked seizures resolve, reassess need for ongoing ASM before discharge; do not continue automatically."]}]}]}, {"id": "connections", "title": "Cross-Day Connections", "group": "Quick Reference", "kind": "notes", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Day 7 topic</strong>", "<strong>Cross-reference</strong>", "<strong>Learning link</strong>"], "rows": [["Resuscitation history", "Day 1 — NRP", "Advanced resuscitation triggers post-resuscitation monitoring and HIE assessment."], ["Ventilation/ABG", "Day 3", "Avoid hypocarbia/hyperoxia extremes; interpret early acidosis in cooling eligibility."], ["Prematurity", "Day 4", "Cooling evidence changes below 36 weeks; IVH/fragility and drug handling differ."], ["Sepsis/meningitis", "Day 5", "Infection is a major alternative cause of encephalopathy/seizure and can coexist with HIE."], ["Jaundice", "Day 6", "Both severe HIE and bilirubin encephalopathy cause neurologic abnormalities; timing/context distinguish them."], ["IVH/PVL follow-up", "Day 11", "Neuroimaging and developmental surveillance principles recur."], ["Epilepsy syndromes", "Day 22", "Today = acute neonatal seizures; later = epilepsy classification and syndromic management."]]}]}]}, {"id": "cases", "title": "Clinical Cases", "group": "Practice", "kind": "cases", "sections": [{"title": "Case 1 — Low Apgar is not the diagnosis", "blocks": [{"t": "p", "html": "Patient / data: 39+1 wk infant after placental abruption, Apgar 2/4/6, ventilated for 12 min. Cord pH 6.96, BD 18. At 90 min infant is lethargic with weak suck and hypotonia."}, {"t": "p", "html": "<strong>Specific question: What is the key diagnostic framing and immediate next step?</strong>"}, {"t": "p", "html": "Structured reasoning: This is neonatal encephalopathy with strong biochemical/perinatal evidence for hypoxic-ischemic injury. The infant requires structured HIE examination and urgent therapeutic-hypothermia eligibility assessment; do not merely label “birth asphyxia” and observe."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Using Apgar alone or waiting for seizures before activating cooling."], "fill": "843C0C"}]}, {"title": "Case 2 — Transient improvement during latent phase", "blocks": [{"t": "p", "html": "Patient / data: Term infant required chest compressions and epinephrine. At 30 min he is more alert; at 2 h he becomes lethargic. pH 7.02, BD 17."}, {"t": "p", "html": "<strong>Specific question: Can the early improvement exclude evolving HIE?</strong>"}, {"t": "p", "html": "Structured reasoning: No. Reperfusion can produce a latent partial-recovery phase before secondary energy failure. Repeat neurologic examination and activate cooling evaluation within the therapeutic window."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Being reassured by a brief “normal” interval."], "fill": "843C0C"}]}, {"title": "Case 3 — Standard cooling candidate", "blocks": [{"t": "p", "html": "Patient / data: 38 wk, 3 h old, cord pH 6.88; ongoing ventilation at 10 min; moderate encephalopathy with weak suck, hypotonia and lethargy."}, {"t": "p", "html": "<strong>Specific question: What is the treatment prescription?</strong>"}, {"t": "p", "html": "Structured reasoning: Begin servo-controlled therapeutic hypothermia promptly: target 33.5°C, continue 72 h, then rewarm ~0.5°C/h with continuous neuromonitoring and multiorgan care."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Delaying cooling for MRI or formal EEG."], "fill": "843C0C"}]}, {"title": "Case 4 — 35+4-week gray zone", "blocks": [{"t": "p", "html": "Patient / data: 35+4 wk infant, 2 h old, severe acidosis and moderate encephalopathy after uterine rupture."}, {"t": "p", "html": "<strong>Specific question: Is cooling automatically standard of care?</strong>"}, {"t": "p", "html": "Structured reasoning: Current AAP 2026 notes limited evidence for 35+0–35+6 weeks. Urgent expert evaluation and parental discussion are needed; risks/uncertain benefits should be documented. It is not the same evidence category as ≥36 weeks."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Applying the ≥36-week recommendation without nuance."], "fill": "843C0C"}]}, {"title": "Case 5 — Bradycardia during cooling", "blocks": [{"t": "p", "html": "Patient / data: 38 wk infant cooled at 33.5°C, HR 82/min, BP 63/38, warm extremities, cap refill 2 s, lactate falling."}, {"t": "p", "html": "<strong>Specific question: What should be done about the heart rate?</strong>"}, {"t": "p", "html": "Structured reasoning: Sinus bradycardia is expected during cooling. With adequate perfusion and blood pressure, observe and assess the whole hemodynamic picture rather than treating the number."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Giving atropine/inotrope solely to normalize HR."], "fill": "843C0C"}]}, {"title": "Case 6 — Jitteriness vs seizure", "blocks": [{"t": "p", "html": "Patient / data: Term infant has symmetric tremulous movements triggered by handling; no eye deviation; movement stops when limb is gently held; glucose 39 mg/dL."}, {"t": "p", "html": "<strong>Specific question: Most likely event and next step?</strong>"}, {"t": "p", "html": "Structured reasoning: Jitteriness from hypoglycemia is more likely than seizure. Correct glucose promptly and reassess; EEG if events persist or become suspicious."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Calling every abnormal movement a seizure and loading phenobarbital before correcting glucose."], "fill": "843C0C"}]}, {"title": "Case 7 — Electroclinical dissociation", "blocks": [{"t": "p", "html": "Patient / data: Infant with HIE had clonic seizures. After phenobarbital, movements stop but continuous EEG shows recurrent evolving rhythmic discharges."}, {"t": "p", "html": "<strong>Specific question: Has seizure control been achieved?</strong>"}, {"t": "p", "html": "Structured reasoning: No. Clinical cessation does not equal electrographic seizure cessation. Treat persistent electrographic seizures and use EEG to judge response."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Stopping therapy because bedside movements disappeared."], "fill": "843C0C"}]}, {"title": "Case 8 — Focal seizures in an otherwise alert term infant", "blocks": [{"t": "p", "html": "Patient / data: 40 wk infant, normal delivery, age 30 h, recurrent right arm clonic seizures, normal glucose and exam between events."}, {"t": "p", "html": "<strong>Specific question: What alternative to HIE should be prioritized?</strong>"}, {"t": "p", "html": "Structured reasoning: Perinatal arterial ischemic stroke is a classic cause of focal neonatal seizures in an otherwise relatively well term infant; obtain EEG and brain imaging."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Assuming all neonatal seizures are HIE."], "fill": "843C0C"}]}, {"title": "Case 9 — aEEG artifact", "blocks": [{"t": "p", "html": "Patient / data: During nursing care, aEEG band abruptly rises. Raw EEG shows large irregular deflections synchronized with handling and no evolving rhythm."}, {"t": "p", "html": "<strong>Specific question: Interpretation?</strong>"}, {"t": "p", "html": "Structured reasoning: Artifact is likely. aEEG seizure suspicion must be confirmed on raw trace/conventional EEG; movement can widen/elevate the band."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Treating the compressed trend display without raw EEG confirmation."], "fill": "843C0C"}]}, {"title": "Case 10 — Prognosis after rewarming", "blocks": [{"t": "p", "html": "Patient / data: Cooled infant had severe early aEEG suppression but improves to continuous background with sleep-wake cycling; MRI shows limited watershed injury."}, {"t": "p", "html": "<strong>Specific question: How should prognosis be communicated?</strong>"}, {"t": "p", "html": "Structured reasoning: Use multimodal probabilistic counseling. Improvement in background is favorable, but MRI pattern, serial exam, seizure burden and later development all matter. Arrange structured follow-up."}, {"t": "callout", "label": "TRAP IDENTIFIED", "title": "", "html": ["Making an absolute prognosis from a single early aEEG snapshot."], "fill": "843C0C"}]}]}, {"id": "data", "title": "Data Interpretation", "group": "Practice", "kind": "data", "sections": [{"title": "", "blocks": [{"t": "table", "head": ["<strong>Station</strong>", "<strong>Data</strong>", "<strong>Interpretation / next step</strong>"], "rows": [["1 — Cooling screen", "38 wk; cord pH 6.92; BD 18; lethargy + weak suck at 2 h", "Meets strong biochemical + moderate encephalopathy framework → initiate TH urgently if no exclusion."], ["2 — Borderline gas", "39 wk; pH 7.10; BD 12; uterine rupture; Apgar 4 at 10 min; moderate encephalopathy", "Borderline biochemical values plus acute event/prolonged depression can satisfy protocol pathway; do not dismiss based on pH alone."], ["3 — aEEG seizure", "Abrupt rise in lower + upper margins with repetitive saw-tooth episodes; raw trace shows evolving rhythmic activity", "Electrographic seizures; quantify burden and treat."], ["4 — aEEG artifact", "Band widens during chest physiotherapy; raw trace has nonphysiologic high-amplitude irregular artifact", "Artifact; fix electrodes/handling and confirm raw EEG before ASM escalation."], ["5 — EEG background", "Burst suppression with prolonged very low-voltage interburst intervals", "Severely abnormal background; integrate medication/cooling effects and serial evolution."], ["6 — MRI pattern", "Bilateral basal ganglia-thalamic + perirolandic restricted diffusion", "Acute profound HIE pattern; high motor-risk phenotype; counsel multimodally."]]}]}]}, {"id": "pearls", "title": "Pearls & Traps", "group": "Practice", "kind": "pearls", "sections": [{"title": "22 Exam Pearls", "blocks": [{"t": "list", "ordered": false, "items": ["Neonatal encephalopathy is a syndrome; HIE is one cause.", "Low Apgar alone does not diagnose asphyxia or HIE.", "The latent phase after reperfusion creates the therapeutic window.", "Standard TH evidence is strongest for ≥36 weeks with moderate-to-severe HIE.", "Current AAP allows individualized consideration at 35+0–35+6 weeks; &lt;35 weeks is not recommended.", "Begin TH as early as possible, ideally within 6 h.", "Do not delay cooling for MRI or conventional EEG.", "Target 33.5°C for 72 h; rewarm ~0.5°C/h.", "Deeper or longer cooling has not shown benefit and may increase harm.", "Avoid hyperthermia in all infants with HIE.", "Bradycardia during cooling can be physiologic if perfusion is adequate.", "Seizures can be electrographic-only.", "Phenobarbital remains first-line for most neonatal seizures.", "Levetiracetam is not automatically superior first-line.", "Correct glucose, calcium, magnesium and sodium abnormalities promptly.", "Focal seizures in a well term infant should raise concern for stroke.", "Clinical seizure cessation after ASM does not prove EEG seizure cessation.", "aEEG is a trend/screening tool, not a replacement for conventional EEG.", "Always inspect raw EEG when aEEG suggests seizure.", "Return of sleep-wake cycling is favorable but not deterministic.", "Diffusion MRI can pseudonormalize; timing matters.", "Prognostication must be multimodal and serial."]}]}, {"title": "15 Traps", "blocks": [{"t": "list", "ordered": false, "items": ["Calling all depressed newborns “HIE” without considering infection, stroke, hemorrhage, drugs or metabolic disease.", "Waiting for seizures before assessing a clearly encephalopathic infant for cooling.", "Cooling mild HIE routinely despite insufficient evidence.", "Using the old blanket “≥35 weeks” statement without acknowledging current AAP 2026 nuance.", "Cooling &lt;35 weeks as routine therapy.", "Starting passive cooling without close temperature monitoring and causing overcooling.", "Using MRI before cooling and losing the therapeutic window.", "Treating expected sinus bradycardia without assessing perfusion.", "Rewarming rapidly and missing hypotension/seizure recurrence.", "Diagnosing seizures solely by abnormal movement without EEG.", "Failing to treat electrographic-only seizures.", "Choosing levetiracetam first simply because it sounds safer.", "Ignoring focal stroke when the infant is otherwise alert.", "Treating aEEG artifact as seizure without raw-trace confirmation.", "Giving an absolute prognosis from one early examination, aEEG or MRI finding."]}]}]}, {"id": "quizzes", "title": "Quizzes", "group": "Practice", "kind": "quizzes", "sections": []}, {"id": "revision", "title": "Rapid Revision", "group": "Revise", "kind": "revision", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": false, "items": ["HIE = neonatal encephalopathy attributable to hypoxic-ischemic injury; low Apgar alone is not enough.", "Latent phase precedes secondary energy failure → explains why cooling should start ideally &lt;6 h.", "Current AAP 2026: routine evidence strongest ≥36 wk; 35+0–35+6 = individualized; &lt;35 = not recommended.", "Standard TH: target 33.5°C, 72 h, rewarm ~0.5°C/h.", "Do not delay cooling for MRI/EEG; do not overcool or prolong to 120 h routinely.", "Continuous EEG is gold standard for neonatal seizures; aEEG is trend/screening adjunct.", "Phenobarbital 20 mg/kg IV = classic first load; treat reversible metabolic/infectious causes simultaneously.", "After ASM, clinical seizure cessation may hide persistent electrographic seizures.", "Focal seizures + relatively well term infant → consider stroke.", "aEEG seizure suspicion must be checked against raw EEG; artifact is common.", "Deep gray/BGT injury = acute profound pattern; watershed injury = partial prolonged pattern.", "Prognosis is serial + multimodal; all cooled HIE infants need neurodevelopmental follow-up."]}]}]}, {"id": "recall", "title": "Active Recall", "group": "Revise", "kind": "recall", "sections": [{"title": "", "blocks": [{"t": "list", "ordered": true, "items": ["Define neonatal encephalopathy and distinguish it from HIE.<br>Answer: Neonatal encephalopathy is a syndrome of disturbed neurologic function (consciousness, tone/reflexes, respiration, feeding, seizures). HIE is neonatal encephalopathy attributable to hypoxic-ischemic injury.", "State the three major temporal phases of hypoxic-ischemic brain injury relevant to cooling.<br>Answer: Primary energy failure → latent partial-recovery phase → secondary energy failure; a later tertiary repair/inflammation phase also contributes to long-term injury.", "Why is the first 6 hours the key therapeutic window?<br>Answer: Cooling is most effective during the latent phase before delayed mitochondrial failure, inflammation and apoptosis are fully established.", "List the clinical domains used in a modified Sarnat examination.<br>Answer: Consciousness, spontaneous activity, posture, tone, primitive reflexes (suck/Moro), autonomic function and seizures/EEG background.", "What HIE severities have established benefit from therapeutic hypothermia?<br>Answer: Moderate-to-severe HIE. Routine cooling for mild HIE remains an evidence gap.", "State the 2026 AAP gestational-age rule for ≥36 wk, 35+0–35+6 wk and &lt;35 wk.<br>Answer: ≥36 0/7 wk: established evidence/recommended when other criteria met. 35 0/7–35 6/7: limited evidence; individualized expert/family discussion. &lt;35 wk: not recommended.", "State the standard cooling target temperature, start window, duration and rewarming rate.<br>Answer: Target 33.5°C; start ideally within 6 h; continue 72 h; rewarm ~0.5°C/h.", "Give the classic severe biochemical trial-entry thresholds for pH and base deficit.<br>Answer: pH ≤7.00 or base deficit ≥16 mmol/L in cord/early blood gas are classic severe biochemical triggers.", "Why can low Apgar not diagnose HIE by itself?<br>Answer: Apgar is nonspecific and affected by prematurity, medications, infection, airway/lung disease, congenital anomalies and resuscitation; it does not establish hypoxic-ischemic etiology.", "Name four common physiologic/hematologic effects during cooling.<br>Answer: Sinus bradycardia, hypotension/low output, thrombocytopenia/coagulopathy, electrolyte/glucose shifts, reduced drug clearance and skin injury risk are examples.", "Why must EEG continue during rewarming?<br>Answer: Seizures can emerge or recur during rewarming; EEG also tracks background recovery.", "Define electroclinical dissociation.<br>Answer: Clinical seizure manifestations stop after ASM while electrographic seizures continue on EEG.", "Name three bedside features favoring seizure over jitteriness.<br>Answer: Spontaneous/stereotyped event, not stimulus-sensitive, persists despite restraint, may have ocular deviation/autonomic change, and has evolving ictal EEG correlate.", "What is the gold-standard test for neonatal seizures?<br>Answer: Conventional multichannel video EEG.", "What is the role of aEEG compared with conventional EEG?<br>Answer: aEEG is a simplified compressed bedside trend for background/cycling/seizure screening; conventional EEG is more sensitive and definitive for diagnosis/localization/morphology.", "How does seizure commonly appear on aEEG?<br>Answer: Sudden elevation of lower and upper margins, often repetitive “saw-tooth” pattern, with evolving ictal activity on raw EEG.", "What is first-line ASM for most neonatal seizures and the classic loading dose?<br>Answer: Phenobarbital; classic first loading dose 20 mg/kg IV.", "Name at least three reasonable second-line ASM options for persistent neonatal seizures.<br>Answer: Additional phenobarbital per protocol, levetiracetam, phenytoin/fosphenytoin, midazolam or lidocaine depending on context; etiology may favor sodium-channel blockers.", "When should neonatal stroke be strongly considered?<br>Answer: Focal seizures in an otherwise relatively well term infant, especially after the first day, should strongly raise concern for perinatal arterial ischemic stroke.", "What MRI pattern suggests acute profound HIE?<br>Answer: Basal ganglia-thalami ± perirolandic cortex/posterior limb internal capsule pattern.", "What MRI pattern suggests partial prolonged HIE?<br>Answer: Parasagittal watershed cortical/subcortical white-matter pattern.", "List four alternative causes of neonatal encephalopathy that can mimic HIE.<br>Answer: Infection/meningoencephalitis, stroke/hemorrhage, hypoglycemia/electrolyte disorder, metabolic/genetic disease, drug exposure/sedation, congenital brain anomaly.", "What factors can confound neurologic examination and EEG interpretation during cooling?<br>Answer: Sedatives/ASMs, hypothermia itself, metabolic abnormalities, organ dysfunction/drug accumulation and technical EEG artifact.", "When may stopping ASM before discharge be appropriate after neonatal seizures?<br>Answer: When acute provoked neonatal seizures have resolved, no ongoing electrographic seizures are present, and neonatal-onset epilepsy is not suspected; individualize with neurology.", "List the major domains required in long-term follow-up after HIE/therapeutic hypothermia.<br>Answer: Motor/cerebral palsy, cognition/language, hearing, vision, feeding/growth, epilepsy, behavior/development and access to early intervention/rehabilitation."]}]}]}, {"id": "notebook", "title": "Error Notebook", "group": "Revise", "kind": "notebook", "sections": []}, {"id": "plan", "title": "Revision Plan", "group": "Revise", "kind": "plan", "sections": [{"title": "Weak-Concept Triage / R1-R2-R3", "h1": "Weak-Concept Triage / R1-R2-R3", "blocks": [{"t": "callout", "label": "NOTEBOOK INTEGRATION", "title": "", "html": ["No Day 7-specific error entry was supplied in this regeneration request. Preserve the existing notebook history. The previously reported Day 5 Jensen BPD-severity knowledge error remains an AMBER item with its planned retest window and should not be falsely marked GREEN merely because Day 7 content changed."], "fill": "1F4E79"}, {"t": "table", "head": ["<strong>Concept</strong>", "<strong>Source</strong>", "<strong>K/C/R/G/S</strong>", "<strong>Failure Count</strong>", "<strong>Status</strong>", "<strong>Next Action</strong>", "<strong>Next Retest</strong>"], "rows": [["Jensen BPD severity: invasive mechanical ventilation at 36 wk PMA = Grade 3", "Prior Day 5 error", "K", "x1", "AMBER", "R1 recall + fresh hidden stem in due window", "6–7 Oct 2026"], ["Day 7 HIE/seizure concepts", "Today", "—", "0", "GREEN/Unassessed", "Move any wrong/guess/uncertain item to AMBER after attempt", "Based on result"]]}]}, {"title": "R1 / R2 / R3 Prompts", "h1": "", "blocks": [{"t": "list", "ordered": false, "items": ["R1 (~24 h): Recite 33.5°C / 6 h / 72 h / 0.5°C per h without looking; explain why the 6-h window exists.", "R2 (~7 d): Re-solve at least 8–10 Day 7 key MCQs, especially cooling eligibility, aEEG limitations and phenobarbital-first-line reasoning.", "R3 (~21 d): Flash-recall HIE MRI patterns, seizure mimics, EEG background patterns and current gestational-age guidance."]}]}, {"title": "Self-Assessment & Performance Tracking", "h1": "Self-Assessment & Performance Tracking", "blocks": [{"t": "table", "head": ["<strong>Metric</strong>", "<strong>Record</strong>"], "rows": [["Base MCQs", "__/75"], ["Correct / Wrong / Unattempted", "__ / __ / __"], ["Accuracy among attempted", "__%"], ["Basic / Recall", "__/7"], ["Conceptual", "__/13"], ["Clinical / Application", "__/27"], ["High-Difficulty", "__/20"], ["Integrated / Rank-Differentiating", "__/8"], ["Close-Distractor questions", "__/__"], ["EEG/aEEG interpretation", "__/__"], ["Guessed-correct / uncertain", "__ / __ (treat as not mastered)"], ["K / C / R / G / S errors", "__ / __ / __ / __ / __"], ["RED / AMBER / GREEN concepts", "__ / __ / __"]]}]}]}, {"id": "references", "title": "References", "group": "More", "kind": "notes", "sections": [{"title": "References — Primary & Supplementary", "h1": "References — Primary & Supplementary", "blocks": [{"t": "list", "ordered": false, "items": ["PRIMARY: Nelson Textbook of Pediatrics, 22nd Edition — neonatal encephalopathy/HIE, neonatal seizures and related neurologic care.", "American Academy of Pediatrics. Therapeutic Hypothermia for Neonatal Hypoxic-Ischemic Encephalopathy: Clinical Report. Pediatrics. 2026.", "2025 American Heart Association / American Academy of Pediatrics Guidelines for Neonatal Resuscitation.", "International League Against Epilepsy (ILAE) Task Force recommendations for treatment of seizures in the neonate.", "Volpe’s Neurology of the Newborn — neonatal encephalopathy, seizures, EEG and MRI pattern interpretation.", "Cloherty &amp; Stark’s Manual of Neonatal Care — NICU protocols, therapeutic hypothermia monitoring and seizure management."]}, {"t": "callout", "label": "FINAL QA CHECK", "title": "", "html": ["Day/date/topic mapping verified • Nelson 22e set as primary textbook • 2026 AAP cooling guidance incorporated • 75-MCQ distribution verified 7/13/27/20/8 • answer key near-balanced and irregular • no calculation drill because 05 Oct 2026 is Monday • 25 Active Recall prompts all have answers • close-distractor items embedded within base count • no future-topic leakage."], "fill": "375623"}]}]}], "quizSets": [{"k": 1, "from": 1, "to": 15, "n": 15}, {"k": 2, "from": 16, "to": 30, "n": 15}, {"k": 3, "from": 31, "to": 45, "n": 15}, {"k": 4, "from": 46, "to": 60, "n": 15}, {"k": 5, "from": 61, "to": 75, "n": 15}], "mcqCount": 75};
